def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Count color frequencies
    colors = {}
    for row in grid:
        for val in row:
            colors[val] = colors.get(val, 0) + 1

    # Background is most frequent color → 2
    bg_color = max(colors.keys(), key=lambda c: colors[c])

    # Find first non-background color (spreader) in reading order
    spreader = None
    for row in grid:
        for val in row:
            if val != bg_color:
                spreader = val
                break
        if spreader:
            break

    # BFS to find all cells reachable from spreader
    n, m = len(grid), len(grid[0])
    visited = [[False] * m for _ in range(n)]
    queue = []

    for r in range(n):
        for c in range(m):
            if grid[r][c] == spreader:
                queue.append((r, c))
                visited[r][c] = True

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                if grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Apply transformation
    new_grid = []
    for r in range(n):
        new_row = []
        for c in range(m):
            if visited[r][c]:
                # Cells reachable from spreader keep spreader color
                new_row.append(grid[r][c])
            elif grid[r][c] == bg_color:
                # Background cells not reachable become 2
                new_row.append(2)
            else:
                # Fixed colors stay same
                new_row.append(grid[r][c])
        new_grid.append(new_row)

    return new_grid
